public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                dfs(grid, visited, i, j, rows, cols);
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, boolean[][] visited, int i, int j, int rows, int cols) {
    if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] == '*' || visited[i][j]) {
        return;
    }

    visited[i][j] = true;

    dfs(grid, visited, i - 1, j, rows, cols); // up
    dfs(grid, visited, i + 1, j, rows, cols); // down
    dfs(grid, visited, i, j - 1, rows, cols); // left
    dfs(grid, visited, i, j + 1, rows, cols); // right
    dfs(grid, visited, i - 1, j - 1, rows, cols); // up-left
    dfs(grid, visited, i - 1, j + 1, rows, cols); // up-right
    dfs(grid, visited, i + 1, j - 1, rows, cols); // down-left
    dfs(grid, visited, i + 1, j + 1, rows, cols); // down-right
}

