    for (int num : nums) {
        sum += num;
    }
    boolean[] possibleAverages = new boolean[sum + 1];
    possibleAverages[0] = true;

    for (int num : nums) {
        for (int j = sum; j >= num; j--) {
            possibleAverages[j] = possibleAverages[j] || possibleAverages[j - num];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (possibleAverages[i * sum / n]) {
            return true;
        }
    }

    return false;
}

