private int backtrack(String s, Set<String> set) {
    if (s.isEmpty()) {
        return set.size();
    }
    int max = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (set.add(prefix)) {
            max = Math.max(max, backtrack(s.substring(i), set));
            set.remove(prefix);
        }
    }
    return max;
}

