public static int squarePermutations(int[] A) {
    if (A == null || A.length <= 1) {
        return 0;
    }

    int N = A.length;
    boolean[] visited = new boolean[N];
    return backtrack(A, visited, 0, new int[N]);
}

private static int backtrack(int[] A, boolean[] visited, int index, int[] current) {
    if (index == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!visited[i] && isPerfectSquare(current[index - 1] + A[i])) {
            visited[i] = true;
            current[index] = A[i];
            count += backtrack(A, visited, index + 1, current);
            visited[i] = false;
        }
    }

    return count;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? -1 : heights[i];

        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }

        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) return new int[0];

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Upward diagonal
            for (int i = Math.min(d, rows - 1); i >= 0 && d - i < cols; i--) {
                result[index++] = mat[i][d - i];
            }
        } else {
            // Downward diagonal
            for (int j = Math.min(d, cols - 1); j >= 0 && d - j < rows; j--) {
                result[index++] = mat[d - j][j];
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the first digit that can be swapped to make the number greater
    int i;
    for (i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, the number is already the greatest permutation
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of digits[i] that is greater than digits[i]
    int j;
    for (j = len - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the position i in ascending order
    Arrays.sort(digits, i + 1, len);

    // Convert the digits back to an integer
    return Integer.parseInt(new String(digits));
}

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        helper(n, n, new char[n], result);
        return result;
    }

private static void helper(int n, int m, char[] arr, List<String> result) {
        if (n == 0) {
            result.add(new String(arr));
            return;
        }
        if (n == 1) {
            result.add(new String(arr) + '0' + new StringBuilder(new String(arr)).reverse());
            result.add(new String(arr) + '1' + new StringBuilder(new String(arr)).reverse());
            result.add(new String(arr) + '8' + new StringBuilder(new String(arr)).reverse());
            return;
        }

        if (n != m) {
            arr[m - n] = '0';
        }

        arr[m + n - 1] = '0';
        helper(n - 2, m, arr, result);
        arr[m + n - 1] = '1';
        helper(n - 2, m, arr, result);
        arr[m + n - 1] = '6';
        helper(n - 2, m, arr, result);
        arr[m + n - 1] = '8';
        helper(n - 2, m, arr, result);
        arr[m + n - 1] = '9';
        helper(n - 2, m, arr, result);
    }

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    // If the area is zero, the points are collinear and do not form a boomerang
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) != 0;
}

